export class VoxelBehavior {
    data;
    constructor(data) {
        this.data = data;
    }
    needUpdate(simulation, x, y, z) {
        if (!this.data.needUpdate)
            return;
        const voxel = simulation.getVoxelForUpdate(x, y, z);
        return this.data.needUpdate(simulation, voxel, x, y, z);
    }
    onInteract(simulation, x, y, z) {
        if (!this.data.onInteract)
            return;
        const voxel = simulation.getVoxelForUpdate(x, y, z);
        this.data.onInteract(simulation, voxel, x, y, z);
    }
    onPaint(simulation, x, y, z) {
        if (!this.data.onPaint)
            return;
        const voxel = simulation.getVoxelForUpdate(x, y, z);
        this.data.onPaint(simulation, voxel, x, y, z);
    }
    onErase(simulation, x, y, z) {
        if (!this.data.onErase)
            return;
        const voxel = simulation.getVoxelForUpdate(x, y, z);
        this.data.onErase(simulation, voxel, x, y, z);
    }
    onTick(simulation, x, y, z) {
        if (!this.data.onTick)
            return;
        const voxel = simulation.getVoxelForUpdate(x, y, z);
        this.data.onTick(simulation, voxel, x, y, z);
    }
}
